package org.daidai.modules.music;

import java.io.*;
import java.nio.charset.Charset;
import java.util.*;

/** Bounded metadata-only readers for common local audio containers. No audio is decoded. */
public final class AudioFileTags {
    private static final int MAX_TAG=16*1024*1024,MAX_PICTURE=8*1024*1024,MAX_TEXT=64*1024;
    public static final class Tags {
        public String title="",artist="",albumArtist="",composer="",arranger="",bpm="";
        public byte[] picture;private int picturePriority=-1;
        public int roundedBpm(){try{double n=Double.parseDouble(bpm.trim());return Double.isFinite(n)&&n>0&&n<=1000?Math.max(1,(int)Math.round(n)):0;}catch(Exception e){return 0;}}
        private void art(byte[] bytes,int type){if(bytes!=null&&bytes.length>0&&bytes.length<=MAX_PICTURE&&(picture==null||type==3&&picturePriority!=3)){picture=bytes;picturePriority=type;}}
    }
    private AudioFileTags(){}
    public static Tags read(InputStream source)throws IOException {
        Tags tags=new Tags();PushbackInputStream in=new PushbackInputStream(new BufferedInputStream(source,32768),16);byte[] header=new byte[12];int count=some(in,header,0,12);in.unread(header,0,count);if(count<4)return tags;
        try {
            if(ascii(header,0,3).equals("ID3"))id3(in,tags);
            else if(ascii(header,0,4).equals("fLaC"))flac(in,tags);
            else if(ascii(header,0,4).equals("OggS"))ogg(in,tags);
            else if(ascii(header,0,4).equals("RIFF")&&count>=12&&ascii(header,8,4).equals("WAVE"))wave(in,tags);
            else if(count>=8&&ascii(header,4,4).equals("ftyp"))mp4(in,Long.MAX_VALUE,0,false,tags,new int[]{0});
            else if((header[0]&255)==0x30&&(header[1]&255)==0x26&&(header[2]&255)==0xb2&&(header[3]&255)==0x75)asf(in,tags);
        }catch(EOFException|IllegalArgumentException|IndexOutOfBoundsException ignored){}return tags;
    }
    private static void id3(InputStream in,Tags t)throws IOException {
        byte[] h=bytes(in,10);int version=h[3]&255;if(version<2||version>4)return;int size=synchsafe(h,6);if(size<0||size>MAX_TAG)return;byte[] data=bytes(in,size);if((h[5]&128)!=0&&version<4)data=unsync(data);
        int at=0;if((h[5]&64)!=0){if(version==2)return;if(data.length<4)return;int ext=version==4?synchsafe(data,0):be32(data,0);if(ext<4||ext>data.length)return;at=version==4?ext:ext+4;}
        while(at+(version==2?6:10)<=data.length){int head=version==2?6:10;String id=ascii(data,at,version==2?3:4);if(id.charAt(0)==0)break;int n=version==2?be24(data,at+3):version==4?synchsafe(data,at+4):be32(data,at+4);if(n<0||n>data.length-at-head)break;int flags=version==2?0:data[at+9]&255;at+=head;byte[] raw=Arrays.copyOfRange(data,at,at+n);at+=n;
            if(version==3&&(flags&0xc0)!=0||version==4&&(flags&0x0c)!=0)continue;
            int prefix=version==3&&(flags&0x20)!=0?1:version==4?((flags&0x40)!=0?1:0)+((flags&1)!=0?4:0):0;if(prefix>raw.length)continue;if(prefix>0)raw=Arrays.copyOfRange(raw,prefix,raw.length);if(version==4&&((h[5]&128)!=0||(flags&2)!=0))raw=unsync(raw);
            if(id.equals("APIC")||id.equals("PIC")){picture(raw,id.equals("PIC"),t);continue;}
            if(raw.length<1||raw.length>MAX_TEXT)continue;String value=idText(raw);if(id.equals("TIT2")||id.equals("TT2"))t.title=value;else if(id.equals("TPE1")||id.equals("TP1"))t.artist=value;else if(id.equals("TPE2")||id.equals("TP2"))t.albumArtist=value;else if(id.equals("TCOM")||id.equals("TCM"))t.composer=value;else if(id.equals("TBPM")||id.equals("TBP"))t.bpm=value;else if(id.equals("TIPL")||id.equals("IPL")||id.equals("IPLS")){involvedPeople(value,t);}else if(id.equals("TXXX")||id.equals("TXX")){int split=textEnd(raw,1,raw[0]&255);if(split<raw.length){String key=decode(raw,1,split-1,raw[0]&255);int next=split+terminator(raw[0]&255);if(next<=raw.length)comment(key,decode(raw,next,raw.length-next,raw[0]&255),t);}}
        }
    }
    private static String idText(byte[] raw){return decode(raw,1,raw.length-1,raw[0]&255).replace('\0',';').trim();}
    private static void picture(byte[] raw,boolean old,Tags t){if(raw.length<6)return;int enc=raw[0]&255,at=old?4:textEnd(raw,1,0)+1;if(at>=raw.length)return;int type=raw[at++]&255;at=textEnd(raw,at,enc)+terminator(enc);if(at>raw.length||raw.length-at>MAX_PICTURE)return;t.art(Arrays.copyOfRange(raw,at,raw.length),type);}
    private static void flac(InputStream in,Tags t)throws IOException {skip(in,4);for(int i=0;i<4096;i++){byte[] h=bytes(in,4);int kind=h[0]&127,n=be24(h,1);if(n>MAX_TAG)return;if(kind==4)vorbis(bytes(in,n),0,t);else if(kind==6)flacPicture(bytes(in,n),t);else skip(in,n);if((h[0]&128)!=0)return;}}
    private static void flacPicture(byte[] b,Tags t){try{int at=0,type=be32(b,at);at+=4;int n=be32(b,at);at+=4;if(n<0||n>b.length-at)return;at+=n;n=be32(b,at);at+=4;if(n<0||n>b.length-at)return;at+=n+16;n=be32(b,at);at+=4;if(n>0&&n<=MAX_PICTURE&&n<=b.length-at)t.art(Arrays.copyOfRange(b,at,at+n),type);}catch(IndexOutOfBoundsException ignored){}}
    private static void vorbis(byte[] b,int start,Tags t){try{int at=start,n=le32(b,at);at+=4;if(n<0||n>b.length-at)return;at+=n;int count=le32(b,at);at+=4;if(count<0||count>10000)return;for(int i=0;i<count;i++){n=le32(b,at);at+=4;if(n<0||n>b.length-at)return;if(n<=MAX_TEXT||n<=MAX_TAG&&n>23&&ascii(b,at,23).equals("METADATA_BLOCK_PICTURE=")){String row=utf8(b,at,n);int equal=row.indexOf('=');if(equal>0)comment(row.substring(0,equal),row.substring(equal+1),t);}at+=n;}}catch(IndexOutOfBoundsException ignored){}}
    private static void comment(String key,String value,Tags t){String rawKey=key==null?"":key.trim();String normalized=normalizeKey(rawKey);value=value==null?"":value.trim();if(normalized.equals("TITLE"))t.title=value;else if(normalized.equals("ARTIST")||normalized.equals("PERFORMER")||normalized.equals("CONTRIBUTING ARTISTS")||normalized.equals("CONTRIBUTING ARTIST")||normalized.equals("INVOLVED PEOPLE")||normalized.equals("INVOLVED PERSON")||rawKey.equals("参与创作的艺术家")||rawKey.equals("参与创作艺术家"))t.artist=append(t.artist,value);else if(normalized.equals("ALBUMARTIST")||normalized.equals("ALBUM ARTIST"))t.albumArtist=append(t.albumArtist,value);else if(normalized.equals("COMPOSER"))t.composer=append(t.composer,value);else if(normalized.equals("ARRANGER"))t.arranger=append(t.arranger,value);else if(normalized.equals("BPM")||normalized.equals("TBPM")||normalized.equals("TEMPO"))t.bpm=value;else if(normalized.equals("METADATA BLOCK PICTURE")){try{if(value.length()<=MAX_PICTURE*4/3+1024)flacPicture(Base64.getDecoder().decode(value),t);}catch(Exception ignored){}}}
    private static String normalizeKey(String key){String value=key.trim().toUpperCase(Locale.ROOT);int colon=value.lastIndexOf(':');if(colon>=0)value=value.substring(colon+1);return value.replace('_',' ').replace('-',' ').replaceAll("\\s+"," ").trim();}
    /** ID3 TIPL/IPLS stores role/name pairs, for example "参与创作的艺术家\0A; B" or "performer\0A". */
    private static void involvedPeople(String value,Tags t){String[] parts=value.split("[;\\n\\r\\x00]+",-1);for(int i=0;i+1<parts.length;i+=2){String role=parts[i].trim();String people=parts[i+1].trim();String normalized=normalizeKey(role);if(normalized.equals("ARTIST")||normalized.equals("PERFORMER")||normalized.equals("CONTRIBUTING ARTISTS")||normalized.equals("CONTRIBUTING ARTIST")||normalized.equals("INVOLVED PEOPLE")||role.equals("参与创作的艺术家")||role.equals("参与创作艺术家"))t.artist=append(t.artist,people);}}
    private static void ogg(InputStream in,Tags t)throws IOException {ByteArrayOutputStream packet=new ByteArrayOutputStream();for(int page=0;page<128;page++){byte[] h=bytes(in,27);if(!ascii(h,0,4).equals("OggS"))return;int seg=h[26]&255;byte[] sizes=bytes(in,seg);for(byte size:sizes){int n=size&255;if(packet.size()+n>MAX_TAG)return;byte[] chunk=bytes(in,n);packet.write(chunk);if(n<255){byte[] b=packet.toByteArray();packet.reset();if(b.length>=7&&b[0]==3&&ascii(b,1,6).equals("vorbis")){vorbis(b,7,t);return;}if(b.length>=8&&ascii(b,0,8).equals("OpusTags")){vorbis(b,8,t);return;}}}}}
    private static void wave(InputStream in,Tags t)throws IOException {skip(in,12);for(int i=0;i<10000;i++){byte[] h=bytes(in,8);long n=le32(h,4)&0xffffffffL;String id=ascii(h,0,4);if(n>MAX_TAG){skip(in,n+(n&1));continue;}if(id.equals("id3 ")||id.equals("ID3 "))id3(new ByteArrayInputStream(bytes(in,(int)n)),t);else if(id.equals("LIST")){byte[] b=bytes(in,(int)n);if(b.length>=4&&ascii(b,0,4).equals("INFO")){int at=4;while(at+8<=b.length){String field=ascii(b,at,4);int len=le32(b,at+4);at+=8;if(len<0||len>b.length-at)break;String value=decode(b,at,Math.min(len,MAX_TEXT),0);if(field.equals("IART"))t.artist=value;else if(field.equals("INAM"))t.title=value;else if(field.equals("IBPM"))t.bpm=value;at+=len+(len&1);}}}else skip(in,n);if((n&1)!=0)skip(in,1);}}
    private static void mp4(InputStream in,long limit,int depth,boolean ilst,Tags t,int[] nodes)throws IOException {if(depth>10)return;long remaining=limit;while(remaining>=8&&++nodes[0]<=20000){byte[] h=new byte[8];if(some(in,h,0,8)<8)return;long n=be32(h,0)&0xffffffffL;int head=8;if(n==1){byte[] ext=bytes(in,8);n=be64(ext,0);head=16;}String id=ascii(h,4,4);if(n==0){if(limit==Long.MAX_VALUE)return;n=remaining;}if(n<head||n>remaining)return;long payload=n-head;if(ilst){if(payload<=MAX_TAG){byte[] box=bytes(in,(int)payload);mp4Tag(id,box,t);}else skip(in,payload);}else if(id.equals("moov")||id.equals("udta")||id.equals("ilst")||id.equals("meta")){if(id.equals("meta")){if(payload<4)return;skip(in,4);payload-=4;}mp4(in,payload,depth+1,id.equals("ilst"),t,nodes);}else skip(in,payload);remaining-=n;}}
    private static void mp4Tag(String id,byte[] b,Tags t){int at=0;String name="";byte[] content=null;while(at+8<=b.length){int n=be32(b,at);if(n<8||n>b.length-at)return;String child=ascii(b,at+4,4);if(child.equals("name")&&n>12)name=utf8(b,at+12,n-12);if(child.equals("data")&&n>=16)content=Arrays.copyOfRange(b,at+16,at+n);at+=n;}if(content==null)return;if(id.equals("covr")){t.art(content,3);return;}String value=content.length<=MAX_TEXT?utf8(content,0,content.length).trim():"";if(id.equals("tmpo")){long n=0;for(byte x:content)n=(n<<8)|(x&255);if(content.length<=4)t.bpm=Long.toString(n);}else if(id.equals("\u00a9ART"))t.artist=value;else if(id.equals("aART"))t.albumArtist=value;else if(id.equals("\u00a9wrt"))t.composer=value;else if(id.equals("\u00a9nam"))t.title=value;else if(id.equals("----"))comment(name,value,t);}
    private static void asf(InputStream in,Tags t)throws IOException {byte[] h=bytes(in,30);long headerSize=le64(h,16);long remaining=headerSize-30;int count=le32(h,24);if(headerSize<30||count<0||count>10000)return;for(int i=0;i<count&&remaining>=24;i++){byte[] object=bytes(in,24);long n=le64(object,16);if(n<24||n>remaining)return;int first=le32(object,0);if(n-24<=MAX_TAG&&(first==0x75b22633||first==0xd2d0a440)){byte[] b=bytes(in,(int)n-24);if(first==0x75b22633){if(b.length<10)return;int title=le16(b,0),artist=le16(b,2);if(10+title+artist<=b.length){t.title=decode(b,10,title,4);t.artist=decode(b,10+title,artist,4);}}else asfFields(b,t);}else skip(in,n-24);remaining-=n;}}
  private static void asfFields(byte[] b,Tags t){try{int count=le16(b,0),at=2;for(int i=0;i<count&&i<10000;i++){int len=le16(b,at);at+=2;String key=decode(b,at,len,4);at+=len;int type=le16(b,at);at+=2;len=le16(b,at);at+=2;if(len<0||len>b.length-at)return;if(key.equals("WM/Picture")&&type==1){int pos=at,picType=b[pos++]&255,n=le32(b,pos);pos+=4;pos=textEnd(b,pos,1)+2;pos=textEnd(b,pos,1)+2;if(n>0&&n<=MAX_PICTURE&&pos+n<=at+len)t.art(Arrays.copyOfRange(b,pos,pos+n),picType);}else {String value=type==0?decode(b,at,len,4):type==3&&len>=4?Long.toString(le32(b,at)&0xffffffffL):"";if(key.equals("WM/BeatsPerMinute"))t.bpm=value;else if(key.equals("WM/Composer"))t.composer=value;else if(key.equals("WM/ContributingArtist")||key.equals("WM/Contributing Artists")||key.equals("WM/Artist")||key.equals("WM/Author")||key.equals("Author"))t.artist=append(t.artist,value);}at+=len;}}catch(IndexOutOfBoundsException ignored){}}
    private static String append(String a,String b){return b.isEmpty()?a:a.isEmpty()?b:a+"; "+b;}
    private static int terminator(int enc){return enc==1||enc==2?2:1;}
    private static int textEnd(byte[] b,int at,int enc){int step=terminator(enc);for(int i=at;i+step<=b.length;i+=step)if(b[i]==0&&(step==1||b[i+1]==0))return i;return b.length;}
    private static String decode(byte[] b,int at,int n,int enc){if(at<0||n<0||at>b.length-n)return "";String cs=enc==1?"UTF-16":enc==2?"UTF-16BE":enc==3?"UTF-8":enc==4?"UTF-16LE":"ISO-8859-1";return new String(b,at,n,Charset.forName(cs)).replace("\ufeff","").replaceAll("\u0000+$","").trim();}
    private static String utf8(byte[] b,int at,int n){return new String(b,at,n,Charset.forName("UTF-8"));}
    private static String ascii(byte[] b,int at,int n){return new String(b,at,n,Charset.forName("ISO-8859-1"));}
    private static byte[] unsync(byte[] b){ByteArrayOutputStream out=new ByteArrayOutputStream(b.length);for(int i=0;i<b.length;i++){out.write(b[i]);if((b[i]&255)==255&&i+1<b.length&&b[i+1]==0)i++;}return out.toByteArray();}
    private static int synchsafe(byte[] b,int p){for(int i=0;i<4;i++)if((b[p+i]&128)!=0)return -1;return (b[p]&127)<<21|(b[p+1]&127)<<14|(b[p+2]&127)<<7|(b[p+3]&127);}
    private static int be24(byte[] b,int p){return (b[p]&255)<<16|(b[p+1]&255)<<8|(b[p+2]&255);}
    private static int be32(byte[] b,int p){return (b[p]&255)<<24|(b[p+1]&255)<<16|(b[p+2]&255)<<8|(b[p+3]&255);}
    private static long be64(byte[] b,int p){return ((long)be32(b,p)<<32)|(be32(b,p+4)&0xffffffffL);}
    private static int le16(byte[] b,int p){return (b[p]&255)|(b[p+1]&255)<<8;}
    private static int le32(byte[] b,int p){return le16(b,p)|le16(b,p+2)<<16;}
    private static long le64(byte[] b,int p){return (le32(b,p)&0xffffffffL)|((long)le32(b,p+4)<<32);}
    private static int some(InputStream in,byte[] b,int p,int n)throws IOException{int at=0;while(at<n){if(Thread.currentThread().isInterrupted())throw new InterruptedIOException();int k=in.read(b,p+at,n-at);if(k<0)break;if(k==0){int x=in.read();if(x<0)break;b[p+at++]=(byte)x;}else at+=k;}return at;}
    private static byte[] bytes(InputStream in,int n)throws IOException{if(n<0||n>MAX_TAG)throw new IOException("Metadata block too large");byte[] b=new byte[n];if(some(in,b,0,n)!=n)throw new EOFException();return b;}
    private static void skip(InputStream in,long n)throws IOException{if(n<0)throw new EOFException();while(n>0){if(Thread.currentThread().isInterrupted())throw new InterruptedIOException();long k=in.skip(n);if(k<=0){if(in.read()<0)throw new EOFException();k=1;}n-=k;}}
}
